11	// AscendC AscendQuantV2 kernel
12	// Performs quantized inference: x * scale [* scale if sqrt_mode] + offset → round → clip → int8
13	// Tile along N dimension, each block processes block_M rows
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 2;
18	
19	// ---------------------------------------------------------------------------
20	// Data movement helpers
21	// ---------------------------------------------------------------------------
22	
23	template <typename T>
24	__aicore__ inline void LoadGmToUb(AscendC::LocalTensor<T> &dst,
25	                                  AscendC::GlobalTensor<T> src,
26	                                  uint32_t count)
27	{
28	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
29	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
30	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
31	}
32	
33	template <typename T>
34	__aicore__ inline void StoreUbToGm(AscendC::GlobalTensor<T> dst,
35	                                    AscendC::LocalTensor<T> &src,
36	                                    uint32_t count)
37	{
38	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
39	    AscendC::DataCopyPad(dst, src, copyParams);
40	}
