42	// Map round_mode int → AscendC Cast RoundMode
43	__aicore__ inline AscendC::RoundMode GetRoundMode(int64_t roundModeFlag)
44	{
45	    // 0=round(RINT), 1=floor, 2=ceil, 3=trunc
46	    if (roundModeFlag == 0) { return AscendC::RoundMode::CAST_RINT; }
47	    if (roundModeFlag == 1) { return AscendC::RoundMode::CAST_FLOOR; }
48	    if (roundModeFlag == 2) { return AscendC::RoundMode::CAST_CEIL; }
49	    return AscendC::RoundMode::CAST_TRUNC; // 3
50	}
