52	// =========================================================================
53	// AscendQuantV2 Kernel  (template parameter SQRT_MODE controls double scale)
54	// =========================================================================
55	
56	template <typename dataType, bool SQRT_MODE>
57	class AscendQuantV2Kernel {
58	public:
59	    __aicore__ inline void Init(
60	        GM_ADDR x, GM_ADDR scale, GM_ADDR offset, GM_ADDR y,
61	        int32_t M, int32_t N, int32_t blockM, int32_t blockN,
62	        int32_t usedCoreNum, int32_t tasksPerCore,
63	        int64_t roundModeFlag, bool perChannel)
64	    {
65	        this->M_ = M;
66	        this->N_ = N;
67	        this->blockM_ = blockM;
68	        this->blockN_ = blockN;
69	        this->usedCoreNum_ = usedCoreNum;
70	        this->tasksPerCore_ = tasksPerCore;
71	        this->roundModeFlag_ = roundModeFlag;
72	        this->perChannel_ = perChannel;
73	
74	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
75	        scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(scale), N);
76	        offsetGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(offset), N);
77	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y), static_cast<uint64_t>(M) * N);
78	
79	        if ASCEND_IS_AIV { InitAivBuffers(); }
80	    }
81	
82	    __aicore__ inline void InitAivBuffers()
83	    {
84	        const int32_t tileElems = blockM_ * blockN_;
85	        const int32_t scaleElems = blockN_;
86	
87	        // Input queues (typed)
88	        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
89	        pipe_.InitBuffer(scaleInQueue_, BUFFER_NUM, scaleElems * sizeof(dataType));
90	        pipe_.InitBuffer(offsetInQueue_, BUFFER_NUM, scaleElems * sizeof(dataType));
91	        // Output queue (int8)
92	        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, tileElems * sizeof(int8_t));
93	
94	        // Compute buffers (float32)
95	        pipe_.InitBuffer(xBuf_, tileElems * sizeof(float));
96	        pipe_.InitBuffer(scaleBuf_, scaleElems * sizeof(float));
97	        pipe_.InitBuffer(scaleBroadBuf_, tileElems * sizeof(float));
98	        pipe_.InitBuffer(offsetBuf_, scaleElems * sizeof(float));
99	        pipe_.InitBuffer(offsetBroadBuf_, tileElems * sizeof(float));
100	        pipe_.InitBuffer(tmpBuf_, tileElems * sizeof(float));
101	        pipe_.InitBuffer(clipBuf_, tileElems * sizeof(float));
102	
103	        // Broadcast tmp (2 * tileElems uint8)
104	        pipe_.InitBuffer(bcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
105	
106	        // Half intermediate buffer for float32 → int8 cast pipeline
107	        pipe_.InitBuffer(halfCastBuf_, tileElems * sizeof(half));
108	
109	        // Cast buffers for fp16/bf16
110	        if constexpr (!std::is_same_v<dataType, float>) {
111	            pipe_.InitBuffer(xCastBuf_, tileElems * sizeof(float));
112	            pipe_.InitBuffer(scaleCastBuf_, scaleElems * sizeof(float));
113	            pipe_.InitBuffer(offsetCastBuf_, scaleElems * sizeof(float));
114	        }
115	    }
116	
117	    __aicore__ inline void Process()
118	    {
119	        if ASCEND_IS_AIV {
120	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
121	            const int subBlockIdx = AscendC::GetSubBlockIdx();
122	            const int subBlockRows = blockM_ / AscendC::GetSubBlockNum();
123	            const int mNum = (M_ + blockM_ - 1) / blockM_;
124	            const int nNum = (N_ + blockN_ - 1) / blockN_;
125	
126	            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
127	                const int bx = coreIdx * tasksPerCore_ + localIdx;
128	                if (bx >= mNum) { continue; }
129	                for (int row = 0; row < subBlockRows; ++row) {
130	                    const int rowIdx = bx * blockM_ + subBlockIdx * subBlockRows + row;
131	                    if (rowIdx >= M_) { continue; }
132	                    ProcessRow(rowIdx, nNum);
133	                }
134	            }
135	        }
136	    }
137	
138	private:
139	    static constexpr int kRowFactor = 1; // process one row at a time
140	
141	    __aicore__ inline void ProcessRow(int rowIdx, int nNum)
142	    {
143	        for (int nTile = 0; nTile < nNum; ++nTile) {
144	            int colBase = nTile * blockN_;
145	            int validN = (colBase + blockN_ <= N_) ? blockN_ : (N_ - colBase);
146	            int tileElems = kRowFactor * validN;
147	
148	            CopyIn(rowIdx, colBase, validN);
149	            Compute(validN);
150	            CopyOut(rowIdx, colBase, validN);
151	        }
152	    }
153	
154	    __aicore__ inline void CopyIn(int rowIdx, int colBase, int validN)
155	    {
156	        // Load x tile
157	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
158	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N_ + colBase],
159	                   static_cast<uint32_t>(validN));
160	        xInQueue_.EnQue(xInLocal_);
161	
162	        // Load scale tile
163	        scaleInLocal_ = scaleInQueue_.AllocTensor<dataType>();
164	        LoadGmToUb(scaleInLocal_, scaleGM_[colBase],
165	                   static_cast<uint32_t>(validN));
166	        scaleInQueue_.EnQue(scaleInLocal_);
167	
168	        // Load offset tile
169	        offsetInLocal_ = offsetInQueue_.AllocTensor<dataType>();
170	        LoadGmToUb(offsetInLocal_, offsetGM_[colBase],
171	                   static_cast<uint32_t>(validN));
172	        offsetInQueue_.EnQue(offsetInLocal_);
173	    }
174	
175	    __aicore__ inline void CopyOut(int rowIdx, int colBase, int validN)
176	    {
177	        yOutLocal_ = yOutQueue_.DeQue<int8_t>();
178	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N_ + colBase],
179	                    yOutLocal_, static_cast<uint32_t>(validN));
180	        yOutQueue_.FreeTensor(yOutLocal_);
181	    }
182	
183	    __aicore__ inline void Compute(int validN)
184	    {
185	        // Allocate output tensor
186	        yOutLocal_ = yOutQueue_.AllocTensor<int8_t>();
187	
188	        // Get compute buffers
189	        xLocal_ = xBuf_.Get<float>();
190	        scaleLocal_ = scaleBuf_.Get<float>();
191	        scaleBroadLocal_ = scaleBroadBuf_.Get<float>();
192	        offsetLocal_ = offsetBuf_.Get<float>();
193	        offsetBroadLocal_ = offsetBroadBuf_.Get<float>();
194	        tmpLocal_ = tmpBuf_.Get<float>();
195	        clipLocal_ = clipBuf_.Get<float>();
196	        bcastTmp_ = bcastTmpBuf_.Get<uint8_t>();
197	
198	        // ---- DeQue inputs and cast to float32 ----
199	        xInLocal_ = xInQueue_.DeQue<dataType>();
200	        PrepareInput(xLocal_, xInLocal_, validN);
201	
202	        scaleInLocal_ = scaleInQueue_.DeQue<dataType>();
203	        PrepareScale(scaleLocal_, scaleInLocal_, validN);
204	
205	        offsetInLocal_ = offsetInQueue_.DeQue<dataType>();
206	        PrepareOffset(offsetLocal_, offsetInLocal_, validN);
207	
208	        // ---- Compute: tmp = x * scale ----
209	        if (perChannel_) {
210	            // Broadcast scale [1, N] → [1, N] (already row-shape, use as-is)
211	            // Since we process 1 row, no broadcast needed: scaleLocal_ is [validN]
212	            AscendC::Mul(tmpLocal_, xLocal_, scaleLocal_, validN);
213	        } else {
214	            // Per-tensor: scale is a single scalar
215	            float scaleVal = scaleLocal_.GetValue(0);
216	            AscendC::Muls(tmpLocal_, xLocal_, scaleVal, validN);
217	        }
218	
219	        // ---- Compute: if sqrt_mode, tmp = tmp * scale ----
220	        if constexpr (SQRT_MODE) {
221	            if (perChannel_) {
222	                AscendC::Mul(tmpLocal_, tmpLocal_, scaleLocal_, validN);
223	            } else {
224	                float scaleVal = scaleLocal_.GetValue(0);
225	                AscendC::Muls(tmpLocal_, tmpLocal_, scaleVal, validN);
226	            }
227	        }
228	
229	        // ---- Compute: tmp = tmp + offset ----
230	        if (perChannel_) {
231	            AscendC::Add(tmpLocal_, tmpLocal_, offsetLocal_, validN);
232	        } else {
233	            // Per-tensor: offset is a scalar; add it inline
234	            float offVal = offsetLocal_.GetValue(0);
235	            AscendC::Adds(tmpLocal_, tmpLocal_, offVal, validN);
236	        }
237	
238	        // ---- Compute: clip to [-128, 127] ----
239	        AscendC::Maxs(clipLocal_, tmpLocal_, -128.0f, validN);
240	        AscendC::Mins(tmpLocal_, clipLocal_, 127.0f, validN);
241	
242	        // ---- Compute: cast float32 → int8 via half intermediate ----
243	        // Direct Cast(float→int8) not supported; use float→half→int8
244	        AscendC::RoundMode roundMode = GetRoundMode(roundModeFlag_);
245	        AscendC::LocalTensor<half> halfTmp = halfCastBuf_.Get<half>();
246	        AscendC::Cast(halfTmp, tmpLocal_, AscendC::RoundMode::CAST_NONE, validN);
247	        AscendC::PipeBarrier<PIPE_V>();
248	        AscendC::Cast(yOutLocal_, halfTmp, roundMode, validN);
249	        AscendC::PipeBarrier<PIPE_V>();
250	
251	        // ---- Free input tensors and enque output ----
252	        xInQueue_.FreeTensor(xInLocal_);
253	        scaleInQueue_.FreeTensor(scaleInLocal_);
254	        offsetInQueue_.FreeTensor(offsetInLocal_);
255	        yOutQueue_.EnQue(yOutLocal_);
256	    }
257	
258	    // ---- Typed → float32 cast helpers ----
259	
260	    __aicore__ inline void PrepareInput(
261	        AscendC::LocalTensor<float> &dst,
262	        AscendC::LocalTensor<dataType> &src,
263	        int count)
264	    {
265	        if constexpr (std::is_same_v<dataType, float>) {
266	            dst = src.template ReinterpretCast<float>();
267	        } else {
268	            AscendC::LocalTensor<float> castBuf = xCastBuf_.Get<float>();
269	            AscendC::Cast(castBuf, src, AscendC::RoundMode::CAST_NONE, count);
270	            AscendC::PipeBarrier<PIPE_V>();
271	            dst = castBuf;
272	        }
273	    }
274	
275	    __aicore__ inline void PrepareScale(
276	        AscendC::LocalTensor<float> &dst,
277	        AscendC::LocalTensor<dataType> &src,
278	        int count)
279	    {
280	        if constexpr (std::is_same_v<dataType, float>) {
281	            dst = src.template ReinterpretCast<float>();
282	        } else {
283	            AscendC::LocalTensor<float> castBuf = scaleCastBuf_.Get<float>();
284	            AscendC::Cast(castBuf, src, AscendC::RoundMode::CAST_NONE, count);
285	            AscendC::PipeBarrier<PIPE_V>();
286	            dst = castBuf;
287	        }
288	    }
289	
290	    __aicore__ inline void PrepareOffset(
291	        AscendC::LocalTensor<float> &dst,
292	        AscendC::LocalTensor<dataType> &src,
293	        int count)
294	    {
295	        if constexpr (std::is_same_v<dataType, float>) {
296	            dst = src.template ReinterpretCast<float>();
297	        } else {
298	            AscendC::LocalTensor<float> castBuf = offsetCastBuf_.Get<float>();
299	            AscendC::Cast(castBuf, src, AscendC::RoundMode::CAST_NONE, count);
300	            AscendC::PipeBarrier<PIPE_V>();
301	            dst = castBuf;
302	        }
303	    }
304	
305	private:
306	    int32_t M_ = 0;
307	    int32_t N_ = 0;
308	    int32_t blockM_ = 0;
309	    int32_t blockN_ = 0;
310	    int32_t usedCoreNum_ = 0;
311	    int32_t tasksPerCore_ = 0;
312	    int64_t roundModeFlag_ = 0;
313	    bool perChannel_ = false;
314	
315	    AscendC::TPipe pipe_;
316	    AscendC::GlobalTensor<dataType> xGM_;
317	    AscendC::GlobalTensor<dataType> scaleGM_;
318	    AscendC::GlobalTensor<dataType> offsetGM_;
319	    AscendC::GlobalTensor<int8_t> yGM_;
320	
