322	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> scaleInQueue_;
323	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> offsetInQueue_;
324	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
325	
326	    AscendC::TBuf<AscendC::TPosition::VECCALC> xBuf_;
327	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;
328	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBroadBuf_;
329	    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBuf_;
330	    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBroadBuf_;
331	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
332	    AscendC::TBuf<AscendC::TPosition::VECCALC> clipBuf_;
333	    AscendC::TBuf<AscendC::TPosition::VECCALC> bcastTmpBuf_;
334	    AscendC::TBuf<AscendC::TPosition::VECCALC> halfCastBuf_;
335	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
336	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleCastBuf_;
337	    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetCastBuf_;
338	
