353	// =========================================================================
354	// Dtype-dispatch helper
355	// =========================================================================
356	
357	template <bool SQRT_MODE>
358	__aicore__ inline void DispatchAscendQuantV2(
359	    GM_ADDR x, GM_ADDR scale, GM_ADDR offset, GM_ADDR y,
360	    int32_t M, int32_t N, int32_t blockM, int32_t blockN,
361	    int32_t usedCoreNum, int32_t tasksPerCore,
362	    int64_t roundModeFlag, bool perChannel,
363	    int64_t dtypeFlag)
364	{
365	    if (dtypeFlag == 0) {
366	        AscendQuantV2Kernel<float, SQRT_MODE> kernel;
367	        kernel.Init(x, scale, offset, y, M, N, blockM, blockN,
368	                    usedCoreNum, tasksPerCore, roundModeFlag, perChannel);
369	        kernel.Process();
370	    } else if (dtypeFlag == 1) {
371	        AscendQuantV2Kernel<half, SQRT_MODE> kernel;
372	        kernel.Init(x, scale, offset, y, M, N, blockM, blockN,
373	                    usedCoreNum, tasksPerCore, roundModeFlag, perChannel);
374	        kernel.Process();
375	    } else {
376	        AscendQuantV2Kernel<bfloat16_t, SQRT_MODE> kernel;
377	        kernel.Init(x, scale, offset, y, M, N, blockM, blockN,
378	                    usedCoreNum, tasksPerCore, roundModeFlag, perChannel);
379	        kernel.Process();
380	    }
381	}
