26	// Tiling constants
27	constexpr int32_t DEFAULT_BLOCK_M = 1;   // process 1 row per tile for simplicity
28	constexpr int32_t DEFAULT_BLOCK_N = 256;  // tile along N dimension
29	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
30	
31	// Map round_mode string to flag: 0=RINT, 1=FLOOR, 2=CEIL, 3=TRUNC
32	static int64_t RoundModeToFlag(const std::string &rm) {
33	    if (rm == "round") return 0;
34	    if (rm == "floor") return 1;
35	    if (rm == "ceil")  return 2;
36	    if (rm == "trunc") return 3;
37	    return 0; // default to round
38	}
39	
40	at::Tensor ascend_quant_v2(
41	    const at::Tensor &x,
42	    const at::Tensor &scale,
43	    const at::Tensor &offset,
44	    int64_t sqrt_mode_i64,
45	    int64_t round_mode_flag,
46	    int64_t per_channel_i64)
47	{
48	    // ---- Input validation ----
49	    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
50	                x.scalar_type() == at::kBFloat16,
51	        "x must be float32, float16, or bfloat16");
52	    TORCH_CHECK(scale.scalar_type() == x.scalar_type(),
53	        "scale must have the same dtype as x");
54	    TORCH_CHECK(offset.scalar_type() == x.scalar_type(),
55	        "offset must have the same dtype as x");
56	    TORCH_CHECK(x.dim() >= 2, "x must have at least 2 dimensions");
57	
58	    // ---- Flatten to 2D ----
59	    auto origShape = x.sizes();
60	    int32_t N = static_cast<int32_t>(x.sizes().back());
61	    int64_t M = x.numel() / N;
62	
63	    at::Tensor x_2d = x.contiguous().view({M, N});
64	    at::Tensor scale_1d = scale.reshape({N}).contiguous();
65	    at::Tensor offset_1d = offset.reshape({N}).contiguous();
66	
67	    // ---- Tiling computation ----
68	    int32_t M_i32 = static_cast<int32_t>(M);
69	    int32_t blockM = DEFAULT_BLOCK_M;
70	    int32_t blockN = DEFAULT_BLOCK_N;
71	    int32_t mNum = (M_i32 + blockM - 1) / blockM;
72	
73	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
74	    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
75	    int32_t usedCoreNum = std::min<int32_t>(
76	        DEFAULT_NUM_PHYSICAL_CORES,
77	        std::max<int32_t>(1, std::min(mNum, coreNum)));
78	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
79	
80	    // Create int8 output tensor
81	    at::Tensor y = at::empty({M, N}, x.options().dtype(at::kChar));
82	
83	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
84	    int64_t dtypeFlag = 0;
85	    if (x_2d.scalar_type() == at::kHalf) {
86	        dtypeFlag = 1;
87	    } else if (x_2d.scalar_type() == at::kBFloat16) {
88	        dtypeFlag = 2;
89	    }
90	
91	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
92	    int32_t _M = M_i32;
93	    int32_t _N = N;
94	    int32_t _blockM = blockM;
95	    int32_t _blockN = blockN;
96	    int32_t _usedCoreNum = usedCoreNum;
97	    int32_t _tasksPerCore = tasksPerCore;
98	    int64_t _roundModeFlag = round_mode_flag;
99	    int64_t _perChannelI64 = per_channel_i64;
100	    int64_t _dtypeFlag = dtypeFlag;
101	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
102	
103	    bool sqrtMode = (sqrt_mode_i64 != 0);
104	
105	    // Dispatch to sqrt or non-sqrt kernel entry
106	    if (sqrtMode) {
107	        EXEC_KERNEL_CMD(ascend_quant_v2_with_sqrt, blockDim,
108	                        x_2d, scale_1d, offset_1d, y,
109	                        _M, _N, _blockM, _blockN,
110	                        _usedCoreNum, _tasksPerCore,
111	                        _roundModeFlag, _perChannelI64, _dtypeFlag);
112	    } else {
113	        EXEC_KERNEL_CMD(ascend_quant_v2_without_sqrt, blockDim,
114	                        x_2d, scale_1d, offset_1d, y,
115	                        _M, _N, _blockM, _blockN,
116	                        _usedCoreNum, _tasksPerCore,
117	                        _roundModeFlag, _perChannelI64, _dtypeFlag);
118	    }
119	
120	    // Reshape output back to original shape
121	    y = y.view(origShape);
122	    return y;
123	}
