46	template <typename T>
47	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
48	{
49	    if constexpr (std::is_same_v<T, bfloat16_t>) {
50	        return AscendC::RoundMode::CAST_ROUND;
51	    }
52	    return AscendC::RoundMode::CAST_NONE;
53	}
54	
55	template <typename T>
56	__aicore__ inline void CastInputToFloat(
57	    AscendC::LocalTensor<float> &dst,
58	    AscendC::LocalTensor<T> &src,
59	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
60	    int32_t count)
61	{
62	    if constexpr (std::is_same_v<T, float>) {
63	        dst = src.template ReinterpretCast<float>();
64	    } else {
65	        dst = castBuf.Get<float>();
66	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
67	        AscendC::PipeBarrier<PIPE_V>();
68	    }
69	}
70	
71	template <typename T>
72	__aicore__ inline void CastOutputBack(
73	    AscendC::LocalTensor<T> &out,
74	    AscendC::LocalTensor<float> &src,
75	    int32_t count)
76	{
77	    if constexpr (!std::is_same_v<T, float>) {
78	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
79	        AscendC::PipeBarrier<PIPE_V>();
80	    }
81	}
