83	// =========================================================================
84	// Strategy 1: merge_n — N <= 1024, merge kMergeRowFactor rows into one tile
85	// =========================================================================
86	
87	template <typename dataType>
88	class AddRmsNormDynamicQuantV2MergeNKernel {
89	public:
90	    static constexpr int kMergeRowFactor = 8;
91	
92	    __aicore__ inline void Init(
93	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta,
94	        GM_ADDR smooth1, GM_ADDR smooth2,
95	        GM_ADDR gq1, GM_ADDR gq2, GM_ADDR y3_fp32, GM_ADDR y4_dtype,
96	        GM_ADDR x_add_out, GM_ADDR scale1, GM_ADDR scale2,
97	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
98	        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
99	        float inv127)
100	    {
101	        this->M = M; this->N = N; this->blockM = blockM;
102	        this->usedCoreNum = usedCoreNum; this->tasksPerCore = tasksPerCore;
103	        this->rowFactor = rowFactor; this->eps = eps;
104	        this->invN = invN; this->inv127 = inv127;
105	
106	        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
107	        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
108	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
109	        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(beta), N);
110	        smooth1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth1), N);
111	        smooth2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth2), N);
112	        gq1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(gq1), static_cast<uint64_t>(M) * N);
113	        gq2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(gq2), static_cast<uint64_t>(M) * N);
114	        y3Fp32GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y3_fp32), static_cast<uint64_t>(M) * N);
115	        y4DtypeGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y4_dtype), static_cast<uint64_t>(M) * N);
116	        xAddGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_add_out), static_cast<uint64_t>(M) * N);
117	        scale1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale1), M);
118	        scale2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale2), M);
119	
120	        if ASCEND_IS_AIV { InitAivBuffers(); }
121	    }
122	
123	    __aicore__ inline void InitAivBuffers()
124	    {
125	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
126	        rowLoops_ = subBlockRows_ / rowFactor;
127	        const int32_t tileElems = kMergeRowFactor * N;
128	
129	        pipe.InitBuffer(x1InQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
130	        pipe.InitBuffer(x2InQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
131	        pipe.InitBuffer(gq1OutQueue_, BUFFER_NUM, tileElems * sizeof(int8_t));
132	        pipe.InitBuffer(gq2OutQueue_, BUFFER_NUM, tileElems * sizeof(int8_t));
133	        pipe.InitBuffer(y3OutQueue_, BUFFER_NUM, tileElems * sizeof(float));
134	        pipe.InitBuffer(y4OutQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
135	        pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, tileElems * sizeof(dataType));
136	        pipe.InitBuffer(scale1OutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(float));
137	        pipe.InitBuffer(scale2OutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(float));
138	
139	        // Pre-load static buffers: gamma only (beta/smooth loaded on-the-fly)
140	        pipe.InitBuffer(gamma1DBuf_, N * sizeof(dataType));
141	        pipe.InitBuffer(gammaTileBuf_, tileElems * sizeof(float));
142	        pipe.InitBuffer(gammaBcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
143	        pipe.InitBuffer(smooth1_1DBuf_, N * sizeof(dataType));
144	        pipe.InitBuffer(smooth1TileBuf_, tileElems * sizeof(float));
145	        pipe.InitBuffer(smooth1BcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
146	        pipe.InitBuffer(smooth2_1DBuf_, N * sizeof(dataType));
147	        pipe.InitBuffer(smooth2TileBuf_, tileElems * sizeof(float));
148	        pipe.InitBuffer(smooth2BcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
149	
150	        // Compute buffers
151	        pipe.InitBuffer(tempBufA_, tileElems * sizeof(float));
152	        pipe.InitBuffer(tempBufB_, tileElems * sizeof(float));
153	        pipe.InitBuffer(tempBufC_, tileElems * sizeof(float));
154	        pipe.InitBuffer(xAddFp32Buf_, tileElems * sizeof(float));
155	        pipe.InitBuffer(yNormFp32Buf_, tileElems * sizeof(float));
156	        pipe.InitBuffer(quantHalfBuf_, tileElems * sizeof(half));
157	        pipe.InitBuffer(reduceTmpBuf_, 2 * tileElems * sizeof(uint8_t));
158	        pipe.InitBuffer(bcastTmpBuf_, 2 * tileElems * sizeof(uint8_t));
159	        pipe.InitBuffer(sumBuf_, kMergeRowFactor * sizeof(float));
160	        pipe.InitBuffer(rstdBuf_, kMergeRowFactor * sizeof(float));
161	        pipe.InitBuffer(scaleBuf_, kMergeRowFactor * sizeof(float));
162	        pipe.InitBuffer(maxAbsBuf_, kMergeRowFactor * sizeof(float));
163	
164	        // Cast buffers for fp16/bf16
165	        if constexpr (!std::is_same_v<dataType, float>) {
166	            pipe.InitBuffer(x1CastBuf_, tileElems * sizeof(float));
167	            pipe.InitBuffer(x2CastBuf_, tileElems * sizeof(float));
168	            pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
169	            pipe.InitBuffer(smooth1CastBuf_, N * sizeof(float));
170	            pipe.InitBuffer(smooth2CastBuf_, N * sizeof(float));
171	            pipe.InitBuffer(xAddCastBuf_, tileElems * sizeof(float));
172	            pipe.InitBuffer(y4CastBuf_, tileElems * sizeof(float));
173	        }
174	
175	        // Pre-load & broadcast gamma
176	        const uint32_t gammaSrcShape[2] = {1U, static_cast<uint32_t>(N)};
177	        const uint32_t gammaDstShape[2] = {
178	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
179	        gammaInLocal_ = gamma1DBuf_.Get<dataType>();
180	        LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
181	        AscendC::PipeBarrier<PIPE_MTE2>();
182	        AscendC::PipeBarrier<PIPE_ALL>();
183	        CastInputToFloat<dataType>(gammaFp32Local_, gammaInLocal_, gammaCastBuf_, N);
184	        gammaTileLocal_ = gammaTileBuf_.Get<float>();
185	        gammaBcastTmpLocal_ = gammaBcastTmpBuf_.Get<uint8_t>();
186	        AscendC::PipeBarrier<PIPE_ALL>();
187	        AscendC::Broadcast<float, 2, 0>(gammaTileLocal_, gammaFp32Local_,
188	            gammaDstShape, gammaSrcShape, gammaBcastTmpLocal_);
189	        AscendC::PipeBarrier<PIPE_V>();
190	    }
191	
192	    __aicore__ inline void Process()
193	    {
194	        if ASCEND_IS_AIV {
195	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
196	            const int subBlockIdx = AscendC::GetSubBlockIdx();
197	
198	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
199	                const int bx = coreIdx * tasksPerCore + localIdx;
200	                if (bx >= (M + blockM - 1) / blockM) { continue; }
201	
202	                for (int r = 0; r < rowLoops_; ++r) {
203	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
204	                    const int validRows = M - rowBase;
205	                    if (validRows > 0) {
206	                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
207	                    }
208	                }
209	            }
210	        }
211	    }
