277	    // Pre-load ANY 1D[N] tensor from GM and broadcast to (kMergeRowFactor, N) float
278	    __aicore__ inline void Preload1D(
279	        AscendC::GlobalTensor<dataType> &gmSrc,
280	        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf1D,
281	        AscendC::TBuf<AscendC::TPosition::VECCALC> &bufTile,
282	        AscendC::TBuf<AscendC::TPosition::VECCALC> &bufBcastTmp,
283	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
284	        AscendC::LocalTensor<dataType> &inLocal,
285	        AscendC::LocalTensor<float> &fp32Local,
286	        AscendC::LocalTensor<float> &tileLocal,
287	        AscendC::LocalTensor<uint8_t> &bcastTmpLocal)
288	    {
289	        inLocal = buf1D.Get<dataType>();
290	        LoadGmToUb(inLocal, gmSrc, static_cast<uint32_t>(N));
291	        AscendC::PipeBarrier<PIPE_MTE2>();
292	        AscendC::PipeBarrier<PIPE_ALL>();
293	        CastInputToFloat<dataType>(fp32Local, inLocal, castBuf, N);
294	        tileLocal = bufTile.Get<float>();
295	        bcastTmpLocal = bufBcastTmp.Get<uint8_t>();
296	        AscendC::PipeBarrier<PIPE_ALL>();
297	        const uint32_t srcShape[2] = {1U, static_cast<uint32_t>(N)};
298	        const uint32_t dstShape[2] = {
299	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
300	        AscendC::Broadcast<float, 2, 0>(tileLocal, fp32Local, dstShape, srcShape, bcastTmpLocal);
301	        AscendC::PipeBarrier<PIPE_V>();
302	    }
303	
304	    __aicore__ inline void ComputeDynamicQuant(
305	        AscendC::LocalTensor<float> &yFp32,
306	        AscendC::LocalTensor<float> &smoothTileFp32,
307	        AscendC::LocalTensor<float> &tempA,
308	        AscendC::LocalTensor<float> &tempB,
309	        AscendC::LocalTensor<float> &tempC,
310	        AscendC::LocalTensor<float> &outScale,
311	        AscendC::LocalTensor<int8_t> &outInt8,
312	        AscendC::LocalTensor<uint8_t> &reduceTmp,
313	        AscendC::LocalTensor<uint8_t> &bcastTmp,
314	        AscendC::LocalTensor<float> &maxAbsBuf,
315	        AscendC::LocalTensor<half> &quantHalf,
316	        int32_t tileSize)
317	    {
318	        const uint32_t reduceShape[2] = {
319	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
320	        const uint32_t scaleSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
321	        const uint32_t scaleDstShape[2] = {
322	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
323	
324	        // smooth_x = y * smooth
325	        AscendC::Mul(tempA, yFp32, smoothTileFp32, tileSize);
326	
327	        // max_abs = reduce_max(|smooth_x|)
328	        AscendC::Abs(tempB, tempA, tileSize);
329	        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::AR, false>(
330	            maxAbsBuf, tempB, reduceTmp, reduceShape, true);
331	
332	        // scale = max(max_abs, 1e-8) * inv127
333	        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, kMergeRowFactor);
334	        AscendC::Muls(outScale, maxAbsBuf, inv127, kMergeRowFactor);
335	
336	        // q = clamp(round(smooth_x / scale), -128, 127)
337	        AscendC::Broadcast<float, 2, 1>(tempC, outScale, scaleDstShape, scaleSrcShape, bcastTmp);
338	        AscendC::Div(tempA, tempA, tempC, tileSize);
339	        AscendC::Maxs(tempA, tempA, -128.0f, tileSize);
340	        AscendC::Mins(tempA, tempA, 127.0f, tileSize);
341	        // Cast: float -> half -> int8
342	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, tileSize);
343	        AscendC::PipeBarrier<PIPE_V>();
344	        AscendC::Cast(outInt8, quantHalf, AscendC::RoundMode::CAST_RINT, tileSize);
345	    }
346	
347	    __aicore__ inline void ComputeRows(int32_t tileSize)
348	    {
349	        gq1OutLocal_ = gq1OutQueue_.AllocTensor<int8_t>();
350	        gq2OutLocal_ = gq2OutQueue_.AllocTensor<int8_t>();
351	        y3OutLocal_ = y3OutQueue_.AllocTensor<float>();
352	        y4OutLocal_ = y4OutQueue_.AllocTensor<dataType>();
353	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
354	        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
355	        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();
356	
357	        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
358	        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
359	        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
360	        AscendC::LocalTensor<float> xAddFp32 = xAddFp32Buf_.Get<float>();
361	        AscendC::LocalTensor<float> yNormFp32 = yNormFp32Buf_.Get<float>();
362	        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
363	        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
364	        AscendC::LocalTensor<float> scaleBuf = scaleBuf_.Get<float>();
365	        AscendC::LocalTensor<float> maxAbsBuf = maxAbsBuf_.Get<float>();
366	        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();
367	        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
368	        AscendC::LocalTensor<uint8_t> bcastTmp = bcastTmpBuf_.Get<uint8_t>();
369	
370	        const uint32_t reduceShape[2] = {
371	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
372	        const uint32_t scaleSrcShape[2] = {static_cast<uint32_t>(kMergeRowFactor), 1U};
373	        const uint32_t scaleDstShape[2] = {
374	            static_cast<uint32_t>(kMergeRowFactor), static_cast<uint32_t>(N)};
375	
376	        // DeQue x1, x2
377	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
378	        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, tileSize);
379	
380	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
381	        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, tileSize);
382	
383	        // ---- Add + RMSNorm (with beta) ----
384	        // x_add = x1 + x2
385	        AscendC::Add(tempC, tempA, tempB, tileSize);
386	        AscendC::DataCopy(xAddFp32, tempC, tileSize);
387	        CastOutputBack<dataType>(xAddOutLocal_, xAddFp32, tileSize);
388	
389	        // x_add^2
390	        AscendC::Mul(tempA, tempC, tempC, tileSize);
391	
392	        // sum_sq = reduce_sum(x_add^2)
393	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
394	            sumBuf, tempA, reduceTmp, reduceShape, true);
395	
396	        // rstd = rsqrt(sum_sq * invN + eps)
397	        AscendC::Muls(rstdBuf, sumBuf, invN, kMergeRowFactor);
398	        AscendC::Adds(rstdBuf, rstdBuf, eps, kMergeRowFactor);
399	        AscendC::Sqrt(rstdBuf, rstdBuf, kMergeRowFactor);
400	        AscendC::Reciprocal(rstdBuf, rstdBuf, kMergeRowFactor);
401	        AscendC::PipeBarrier<PIPE_V>();
402	
403	        // y = x_add * rstd * gamma
404	        AscendC::Broadcast<float, 2, 1>(scaleBuf, rstdBuf, scaleDstShape, scaleSrcShape, bcastTmp);
405	        AscendC::Mul(tempC, xAddFp32, scaleBuf, tileSize);
406	        AscendC::Mul(tempC, tempC, gammaTileLocal_, tileSize);
407	
408	        // V2: Add beta (RMSNorm bias) - load beta on-the-fly
409	        // Reuse smooth1 buffer pair for beta (loaded on-the-fly, used once then discarded)
410	        {
411	            AscendC::LocalTensor<dataType> betaIn;
412	            AscendC::LocalTensor<float> betaFp32;
413	            AscendC::LocalTensor<float> betaTile;
414	            AscendC::LocalTensor<uint8_t> betaBcastTmp;
415	            Preload1D(betaGM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
416	                smooth1CastBuf_, betaIn, betaFp32, betaTile, betaBcastTmp);
417	            AscendC::Add(tempC, tempC, betaTile, tileSize);
418	        }
419	
420	        // Save y (FP32)
421	        AscendC::DataCopy(yNormFp32, tempC, tileSize);
422	        AscendC::DataCopy(y3OutLocal_, yNormFp32, tileSize);
423	
424	        // Write y4_out (orig dtype)
425	        if constexpr (std::is_same_v<dataType, float>) {
426	            AscendC::DataCopy(y4OutLocal_, yNormFp32, tileSize);
427	        } else {
428	            CastOutputBack<dataType>(y4OutLocal_, yNormFp32, tileSize);
429	        }
430	
431	        // ---- DynamicQuant 1 ----
432	        AscendC::LocalTensor<dataType> smooth1InLocal;
433	        AscendC::LocalTensor<float> smooth1Fp32Local;
434	        AscendC::LocalTensor<float> smooth1TileLocal;
435	        AscendC::LocalTensor<uint8_t> smooth1BcastTmp;
436	        Preload1D(smooth1GM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
437	            smooth1CastBuf_, smooth1InLocal, smooth1Fp32Local, smooth1TileLocal, smooth1BcastTmp);
438	
439	        ComputeDynamicQuant(yNormFp32, smooth1TileLocal, tempA, tempB, xAddFp32,
440	            scale1OutLocal_, gq1OutLocal_, reduceTmp, bcastTmp, maxAbsBuf, quantHalf, tileSize);
441	
442	        // ---- DynamicQuant 2 ----
443	        AscendC::LocalTensor<dataType> smooth2InLocal;
444	        AscendC::LocalTensor<float> smooth2Fp32Local;
445	        AscendC::LocalTensor<float> smooth2TileLocal;
446	        AscendC::LocalTensor<uint8_t> smooth2BcastTmp;
447	        Preload1D(smooth2GM_, smooth2_1DBuf_, smooth2TileBuf_, smooth2BcastTmpBuf_,
448	            smooth2CastBuf_, smooth2InLocal, smooth2Fp32Local, smooth2TileLocal, smooth2BcastTmp);
449	
450	        ComputeDynamicQuant(yNormFp32, smooth2TileLocal, tempA, tempB, xAddFp32,
451	            scale2OutLocal_, gq2OutLocal_, reduceTmp, bcastTmp, maxAbsBuf, quantHalf, tileSize);
452	
453	        // EnQue outputs
454	        x1InQueue_.FreeTensor(x1InLocal_);
455	        x2InQueue_.FreeTensor(x2InLocal_);
456	        gq1OutQueue_.EnQue(gq1OutLocal_);
457	        gq2OutQueue_.EnQue(gq2OutLocal_);
458	        y3OutQueue_.EnQue(y3OutLocal_);
459	        y4OutQueue_.EnQue(y4OutLocal_);
460	        xAddOutQueue_.EnQue(xAddOutLocal_);
461	        scale1OutQueue_.EnQue(scale1OutLocal_);
462	        scale2OutQueue_.EnQue(scale2OutLocal_);
463	    }
464	
465	    // Single-row fallback (validRows < kMergeRowFactor)
466	    __aicore__ inline void ComputeSingleRow()
467	    {
468	        gq1OutLocal_ = gq1OutQueue_.AllocTensor<int8_t>();
469	        gq2OutLocal_ = gq2OutQueue_.AllocTensor<int8_t>();
470	        y3OutLocal_ = y3OutQueue_.AllocTensor<float>();
471	        y4OutLocal_ = y4OutQueue_.AllocTensor<dataType>();
472	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
473	        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
474	        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();
475	
476	        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
477	        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
478	        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
479	        AscendC::LocalTensor<float> xAddFp32 = xAddFp32Buf_.Get<float>();
480	        AscendC::LocalTensor<float> yNormFp32 = yNormFp32Buf_.Get<float>();
481	        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
482	        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
483	        AscendC::LocalTensor<float> maxAbsBuf = maxAbsBuf_.Get<float>();
484	        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();
485	        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
486	        AscendC::LocalTensor<uint8_t> bcastTmp = bcastTmpBuf_.Get<uint8_t>();
487	
488	        const uint32_t rowReduceShape[2] = {1U, static_cast<uint32_t>(N)};
489	        const uint32_t qScaleSrcShape[2] = {1U, 1U};
490	        const uint32_t qScaleDstShape[2] = {1U, static_cast<uint32_t>(N)};
491	
492	        // DeQue x1, x2
493	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
494	        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, N);
495	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
496	        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, N);
497	
498	        // x_add = x1 + x2
499	        AscendC::Add(tempC, tempA, tempB, N);
500	        AscendC::DataCopy(xAddFp32, tempC, N);
501	        CastOutputBack<dataType>(xAddOutLocal_, xAddFp32, N);
502	
503	        // sum_sq
504	        AscendC::Mul(tempA, tempC, tempC, N);
505	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::RA, false>(
506	            sumBuf, tempA, reduceTmp, rowReduceShape, true);
507	        float meanSq = sumBuf.GetValue(0) * invN + eps;
508	        AscendC::Duplicate(sumBuf, meanSq, 1);
509	        AscendC::Rsqrt(rstdBuf, sumBuf, 1);
510	        AscendC::PipeBarrier<PIPE_ALL>();
511	        float invRmsVal = rstdBuf.GetValue(0);
512	        AscendC::PipeBarrier<PIPE_ALL>();
513	
514	        // y = x_add * rstd * gamma
515	        AscendC::Muls(tempC, xAddFp32, invRmsVal, N);
516	        AscendC::Mul(tempC, tempC, gammaTileLocal_, N);
517	
518	        // V2: Add beta
519	        {
520	            AscendC::LocalTensor<dataType> betaIn;
521	            AscendC::LocalTensor<float> betaFp32;
522	            AscendC::LocalTensor<float> betaTile;
523	            AscendC::LocalTensor<uint8_t> betaBcastTmp;
524	            Preload1D(betaGM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
525	                smooth1CastBuf_, betaIn, betaFp32, betaTile, betaBcastTmp);
526	            AscendC::Add(tempC, tempC, betaTile, N);
527	        }
528	
529	        // Save y
530	        AscendC::DataCopy(yNormFp32, tempC, N);
531	        AscendC::DataCopy(y3OutLocal_, yNormFp32, N);
532	
533	        if constexpr (std::is_same_v<dataType, float>) {
534	            AscendC::DataCopy(y4OutLocal_, yNormFp32, N);
535	        } else {
536	            CastOutputBack<dataType>(y4OutLocal_, yNormFp32, N);
537	        }
538	
539	        // DynamicQuant 1
540	        AscendC::LocalTensor<dataType> smooth1InLocal;
541	        AscendC::LocalTensor<float> smooth1Fp32Local;
542	        AscendC::LocalTensor<float> smooth1TileLocal;
543	        AscendC::LocalTensor<uint8_t> smooth1BcastTmp;
544	        Preload1D(smooth1GM_, smooth1_1DBuf_, smooth1TileBuf_, smooth1BcastTmpBuf_,
545	            smooth1CastBuf_, smooth1InLocal, smooth1Fp32Local, smooth1TileLocal, smooth1BcastTmp);
546	
547	        AscendC::Mul(tempA, yNormFp32, smooth1TileLocal, N);
548	        AscendC::Abs(tempB, tempA, N);
549	        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::RA, false>(
550	            maxAbsBuf, tempB, reduceTmp, rowReduceShape, true);
551	        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, 1);
552	        AscendC::PipeBarrier<PIPE_V>();
553	        AscendC::Muls(scale1OutLocal_, maxAbsBuf, inv127, 1);
554	
555	        AscendC::Broadcast<float, 2, 1>(tempB, scale1OutLocal_, qScaleDstShape, qScaleSrcShape, bcastTmp);
556	        AscendC::Div(tempA, tempA, tempB, N);
557	        AscendC::Maxs(tempA, tempA, -128.0f, N);
558	        AscendC::Mins(tempA, tempA, 127.0f, N);
559	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
560	        AscendC::PipeBarrier<PIPE_V>();
561	        AscendC::Cast(gq1OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);
562	
563	        // DynamicQuant 2
564	        AscendC::LocalTensor<dataType> smooth2InLocal;
565	        AscendC::LocalTensor<float> smooth2Fp32Local;
566	        AscendC::LocalTensor<float> smooth2TileLocal;
567	        AscendC::LocalTensor<uint8_t> smooth2BcastTmp;
568	        Preload1D(smooth2GM_, smooth2_1DBuf_, smooth2TileBuf_, smooth2BcastTmpBuf_,
569	            smooth2CastBuf_, smooth2InLocal, smooth2Fp32Local, smooth2TileLocal, smooth2BcastTmp);
570	
571	        AscendC::Mul(tempA, yNormFp32, smooth2TileLocal, N);
572	        AscendC::Abs(tempB, tempA, N);
573	        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::RA, false>(
574	            maxAbsBuf, tempB, reduceTmp, rowReduceShape, true);
575	        AscendC::Maxs(maxAbsBuf, maxAbsBuf, 1e-8f, 1);
576	        AscendC::Muls(scale2OutLocal_, maxAbsBuf, inv127, 1);
577	
578	        AscendC::Broadcast<float, 2, 1>(tempB, scale2OutLocal_, qScaleDstShape, qScaleSrcShape, bcastTmp);
579	        AscendC::Div(tempA, tempA, tempB, N);
580	        AscendC::Maxs(tempA, tempA, -128.0f, N);
581	        AscendC::Mins(tempA, tempA, 127.0f, N);
582	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
583	        AscendC::PipeBarrier<PIPE_V>();
584	        AscendC::Cast(gq2OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);
585	
586	        x1InQueue_.FreeTensor(x1InLocal_);
587	        x2InQueue_.FreeTensor(x2InLocal_);
588	        gq1OutQueue_.EnQue(gq1OutLocal_);
589	        gq2OutQueue_.EnQue(gq2OutLocal_);
590	        y3OutQueue_.EnQue(y3OutLocal_);
591	        y4OutQueue_.EnQue(y4OutLocal_);
592	        xAddOutQueue_.EnQue(xAddOutLocal_);
593	        scale1OutQueue_.EnQue(scale1OutLocal_);
594	        scale2OutQueue_.EnQue(scale2OutLocal_);
595	    }
