597	    __aicore__ inline void ProcessSingleRow(int32_t rowIdx)
598	    {
599	        CopyInX1(rowIdx, N);
600	        CopyInX2(rowIdx, N);
601	        ComputeSingleRow();
602	        CopyOutGq1(rowIdx, N);
603	        CopyOutGq2(rowIdx, N);
604	        CopyOutY3Fp32(rowIdx, N);
605	        CopyOutY4Dtype(rowIdx, N);
606	        CopyOutXAdd(rowIdx, N);
607	        CopyOutScale1(rowIdx, 1);
608	        CopyOutScale2(rowIdx, 1);
609	    }
610	
611	    __aicore__ inline void ProcessRows(int32_t rowBase, int32_t validRows)
612	    {
613	        if (validRows < kMergeRowFactor) {
614	            for (int r = 0; r < validRows; ++r) {
615	                ProcessSingleRow(rowBase + r);
616	            }
617	            return;
618	        }
619	        const int32_t tileSize = kMergeRowFactor * N;
620	        CopyInX1(rowBase, tileSize);
621	        CopyInX2(rowBase, tileSize);
622	        ComputeRows(tileSize);
623	        CopyOutGq1(rowBase, tileSize);
624	        CopyOutGq2(rowBase, tileSize);
625	        CopyOutY3Fp32(rowBase, tileSize);
626	        CopyOutY4Dtype(rowBase, tileSize);
627	        CopyOutXAdd(rowBase, tileSize);
628	        CopyOutScale1(rowBase, kMergeRowFactor);
629	        CopyOutScale2(rowBase, kMergeRowFactor);
630	    }
