681	// =========================================================================
682	// Strategy 2: single_row — N > 1024, one row at a time
683	// =========================================================================
684	
685	template <typename dataType>
686	class AddRmsNormDynamicQuantV2SingleRowKernel {
687	public:
688	    __aicore__ inline void Init(
689	        GM_ADDR x1, GM_ADDR x2, GM_ADDR gamma, GM_ADDR beta,
690	        GM_ADDR smooth1, GM_ADDR smooth2,
691	        GM_ADDR gq1, GM_ADDR gq2, GM_ADDR y3_fp32, GM_ADDR y4_dtype,
692	        GM_ADDR x_add_out, GM_ADDR scale1, GM_ADDR scale2,
693	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
694	        int32_t tasksPerCore, float eps, float invN,
695	        float inv127)
696	    {
697	        this->M = M; this->N = N; this->blockM = blockM;
698	        this->usedCoreNum = usedCoreNum; this->tasksPerCore = tasksPerCore;
699	        this->eps = eps; this->invN = invN; this->inv127 = inv127;
700	
701	        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1), static_cast<uint64_t>(M) * N);
702	        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2), static_cast<uint64_t>(M) * N);
703	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
704	        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(beta), N);
705	        smooth1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth1), N);
706	        smooth2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth2), N);
707	        gq1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(gq1), static_cast<uint64_t>(M) * N);
708	        gq2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(gq2), static_cast<uint64_t>(M) * N);
709	        y3Fp32GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y3_fp32), static_cast<uint64_t>(M) * N);
710	        y4DtypeGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y4_dtype), static_cast<uint64_t>(M) * N);
711	        xAddGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_add_out), static_cast<uint64_t>(M) * N);
712	        scale1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale1), M);
713	        scale2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale2), M);
714	
715	        if ASCEND_IS_AIV {
716	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
717	
718	            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
719	            pipe.InitBuffer(smooth1Buf_, N * sizeof(dataType));
720	            pipe.InitBuffer(smooth2Buf_, N * sizeof(dataType));
721	            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N * sizeof(dataType));
722	            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N * sizeof(dataType));
723	            pipe.InitBuffer(gq1OutQueue_, BUFFER_NUM, N * sizeof(int8_t));
724	            pipe.InitBuffer(gq2OutQueue_, BUFFER_NUM, N * sizeof(int8_t));
725	            pipe.InitBuffer(y3OutQueue_, BUFFER_NUM, N * sizeof(float));
726	            pipe.InitBuffer(y4OutQueue_, BUFFER_NUM, N * sizeof(dataType));
727	            pipe.InitBuffer(xAddOutQueue_, BUFFER_NUM, N * sizeof(dataType));
728	            pipe.InitBuffer(scale1OutQueue_, BUFFER_NUM, sizeof(float));
729	            pipe.InitBuffer(scale2OutQueue_, BUFFER_NUM, sizeof(float));
730	
731	            pipe.InitBuffer(tempBufA_, N * sizeof(float));
732	            pipe.InitBuffer(tempBufB_, N * sizeof(float));
733	            pipe.InitBuffer(tempBufC_, N * sizeof(float));
734	            pipe.InitBuffer(yNormFp32Buf_, N * sizeof(float));
735	            pipe.InitBuffer(quantHalfBuf_, N * sizeof(half));
736	            pipe.InitBuffer(reduceTmpBuf_, 2 * N * sizeof(float));
737	            pipe.InitBuffer(bcastTmpBuf_, 2 * N * sizeof(uint8_t));
738	            pipe.InitBuffer(sumBuf_, sizeof(float));
739	            pipe.InitBuffer(rstdBuf_, sizeof(float));
740	
741	            if constexpr (!std::is_same_v<dataType, float>) {
742	                pipe.InitBuffer(x1CastBuf_, N * sizeof(float));
743	                pipe.InitBuffer(x2CastBuf_, N * sizeof(float));
744	                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
745	                pipe.InitBuffer(smooth1CastBuf_, N * sizeof(float));
746	                pipe.InitBuffer(smooth2CastBuf_, N * sizeof(float));
747	                pipe.InitBuffer(xAddCastBuf_, N * sizeof(float));
748	                pipe.InitBuffer(y4CastBuf_, N * sizeof(float));
749	            }
750	
751	            // Pre-load gamma, smooth1, smooth2
752	            gammaInLocal_ = gammaBuf_.Get<dataType>();
753	            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
754	            CastInputToFloat<dataType>(gammaFp32Local_, gammaInLocal_, gammaCastBuf_, N);
755	
756	            smooth1InLocal_ = smooth1Buf_.Get<dataType>();
757	            LoadGmToUb(smooth1InLocal_, smooth1GM_, static_cast<uint32_t>(N));
758	            CastInputToFloat<dataType>(smooth1Fp32Local_, smooth1InLocal_, smooth1CastBuf_, N);
759	
760	            smooth2InLocal_ = smooth2Buf_.Get<dataType>();
761	            LoadGmToUb(smooth2InLocal_, smooth2GM_, static_cast<uint32_t>(N));
762	            CastInputToFloat<dataType>(smooth2Fp32Local_, smooth2InLocal_, smooth2CastBuf_, N);
763	        }
764	    }
765	
766	    __aicore__ inline void Process()
767	    {
768	        if ASCEND_IS_AIV {
769	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
770	            const int subBlockIdx = AscendC::GetSubBlockIdx();
771	            const int mNum = (M + blockM - 1) / blockM;
772	
773	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
774	                const int bx = coreIdx * tasksPerCore + localIdx;
775	                if (bx >= mNum) { continue; }
776	                for (int row = 0; row < subBlockRows_; ++row) {
777	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
778	                    if (rowIdx < M) { ProcessRow(rowIdx); }
779	                }
780	            }
781	        }
782	    }
