848	    // Load and broadcast 1D beta on-the-fly using temp buffers
849	    __aicore__ inline void LoadBeta1D(
850	        AscendC::LocalTensor<float> &betaFp32,
851	        AscendC::LocalTensor<float> &tempA,
852	        AscendC::LocalTensor<float> &tempB)
853	    {
854	        AscendC::LocalTensor<dataType> betaIn = tempBufA_.Get<dataType>();
855	        LoadGmToUb(betaIn, betaGM_, static_cast<uint32_t>(N));
856	        AscendC::PipeBarrier<PIPE_MTE2>();
857	        AscendC::PipeBarrier<PIPE_ALL>();
858	        // Cast to float32 into tempC
859	        AscendC::LocalTensor<float> castBuf = yNormFp32Buf_.Get<float>();
860	        CastInputToFloat<dataType>(betaFp32, betaIn, x1CastBuf_, N);
861	        AscendC::DataCopy(betaFp32, betaFp32, N);
862	    }
863	
864	    __aicore__ inline void ComputeRow()
865	    {
866	        gq1OutLocal_ = gq1OutQueue_.AllocTensor<int8_t>();
867	        gq2OutLocal_ = gq2OutQueue_.AllocTensor<int8_t>();
868	        y3OutLocal_ = y3OutQueue_.AllocTensor<float>();
869	        y4OutLocal_ = y4OutQueue_.AllocTensor<dataType>();
870	        xAddOutLocal_ = xAddOutQueue_.AllocTensor<dataType>();
871	        scale1OutLocal_ = scale1OutQueue_.AllocTensor<float>();
872	        scale2OutLocal_ = scale2OutQueue_.AllocTensor<float>();
873	
874	        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
875	        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
876	        AscendC::LocalTensor<float> tempC = tempBufC_.Get<float>();
877	        AscendC::LocalTensor<float> yNormFp32 = yNormFp32Buf_.Get<float>();
878	        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
879	        AscendC::LocalTensor<float> sumBuf = sumBuf_.Get<float>();
880	        AscendC::LocalTensor<float> rstdBuf = rstdBuf_.Get<float>();
881	        AscendC::LocalTensor<float> reduceTmp = reduceTmpBuf_.Get<float>();
882	
883	        // DeQue x1, x2
884	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
885	        CastInputToFloat<dataType>(tempA, x1InLocal_, x1CastBuf_, N);
886	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
887	        CastInputToFloat<dataType>(tempB, x2InLocal_, x2CastBuf_, N);
888	
889	        // ---- Add + RMSNorm (with beta) ----
890	        // x_add = x1 + x2
891	        AscendC::Add(tempC, tempA, tempB, N);
892	        CastOutputBack<dataType>(xAddOutLocal_, tempC, N);
893	
894	        // sum_sq
895	        AscendC::Mul(tempA, tempC, tempC, N);
896	        AscendC::ReduceSum<float>(sumBuf, tempA, reduceTmp, N);
897	
898	        float meanSq = sumBuf.GetValue(0) * invN + eps;
899	        AscendC::Duplicate(sumBuf, meanSq, 1);
900	        AscendC::Rsqrt(rstdBuf, sumBuf, 1);
901	        AscendC::PipeBarrier<PIPE_ALL>();
902	        float invRmsVal = rstdBuf.GetValue(0);
903	        AscendC::PipeBarrier<PIPE_ALL>();
904	
905	        // y = x_add * rstd * gamma
906	        AscendC::Muls(tempC, tempC, invRmsVal, N);
907	        AscendC::Mul(tempC, tempC, gammaFp32Local_, N);
908	
909	        // V2: Add beta — load beta 1D from GM, add elementwise
910	        {
911	            AscendC::LocalTensor<dataType> betaInLocal;
912	            AscendC::LocalTensor<float> betaFp32Local;
913	            betaInLocal = tempBufA_.Get<dataType>();
914	            // beta 1D: load from GM, cast
915	            LoadGmToUb(betaInLocal, betaGM_, static_cast<uint32_t>(N));
916	            AscendC::PipeBarrier<PIPE_MTE2>();
917	            AscendC::PipeBarrier<PIPE_ALL>();
918	            CastInputToFloat<dataType>(betaFp32Local, betaInLocal, x1CastBuf_, N);
919	            AscendC::Add(tempC, tempC, betaFp32Local, N);
920	        }
921	
922	        // Save y
923	        AscendC::DataCopy(yNormFp32, tempC, N);
924	        AscendC::DataCopy(y3OutLocal_, yNormFp32, N);
925	
926	        if constexpr (std::is_same_v<dataType, float>) {
927	            AscendC::DataCopy(y4OutLocal_, yNormFp32, N);
928	        } else {
929	            CastOutputBack<dataType>(y4OutLocal_, yNormFp32, N);
930	        }
931	
932	        // ---- DynamicQuant 1 ----
933	        AscendC::Mul(tempA, yNormFp32, smooth1Fp32Local_, N);
934	        AscendC::Abs(tempB, tempA, N);
935	        AscendC::ReduceMax<float>(sumBuf, tempB, reduceTmp, N);
936	        AscendC::PipeBarrier<PIPE_ALL>();
937	        float maxAbs1 = sumBuf.GetValue(0);
938	        maxAbs1 = (maxAbs1 > 1e-8f) ? maxAbs1 : 1e-8f;
939	
940	        float scale1Val = maxAbs1 * inv127;
941	        AscendC::Duplicate(scale1OutLocal_, scale1Val, 1);
942	
943	        AscendC::Muls(tempA, tempA, 1.0f / scale1Val, N);
944	        AscendC::Maxs(tempA, tempA, -128.0f, N);
945	        AscendC::Mins(tempA, tempA, 127.0f, N);
946	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
947	        AscendC::PipeBarrier<PIPE_V>();
948	        AscendC::Cast(gq1OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);
949	
950	        // ---- DynamicQuant 2 ----
951	        AscendC::Mul(tempA, yNormFp32, smooth2Fp32Local_, N);
952	        AscendC::Abs(tempB, tempA, N);
953	        AscendC::ReduceMax<float>(sumBuf, tempB, reduceTmp, N);
954	        AscendC::PipeBarrier<PIPE_ALL>();
955	        float maxAbs2 = sumBuf.GetValue(0);
956	        maxAbs2 = (maxAbs2 > 1e-8f) ? maxAbs2 : 1e-8f;
957	
958	        float scale2Val = maxAbs2 * inv127;
959	        AscendC::Duplicate(scale2OutLocal_, scale2Val, 1);
960	
961	        AscendC::Muls(tempA, tempA, 1.0f / scale2Val, N);
962	        AscendC::Maxs(tempA, tempA, -128.0f, N);
963	        AscendC::Mins(tempA, tempA, 127.0f, N);
964	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N);
965	        AscendC::PipeBarrier<PIPE_V>();
966	        AscendC::Cast(gq2OutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N);
967	
968	        x1InQueue_.FreeTensor(x1InLocal_);
969	        x2InQueue_.FreeTensor(x2InLocal_);
970	        gq1OutQueue_.EnQue(gq1OutLocal_);
971	        gq2OutQueue_.EnQue(gq2OutLocal_);
972	        y3OutQueue_.EnQue(y3OutLocal_);
973	        y4OutQueue_.EnQue(y4OutLocal_);
974	        xAddOutQueue_.EnQue(xAddOutLocal_);
975	        scale1OutQueue_.EnQue(scale1OutLocal_);
976	        scale2OutQueue_.EnQue(scale2OutLocal_);
977	    }
978	
979	    __aicore__ inline void ProcessRow(int32_t rowIdx)
980	    {
981	        CopyInX1(rowIdx);
982	        CopyInX2(rowIdx);
983	        ComputeRow();
984	        CopyOutGq1(rowIdx);
985	        CopyOutGq2(rowIdx);
986	        CopyOutY3(rowIdx);
987	        CopyOutY4(rowIdx);
988	        CopyOutXAdd(rowIdx);
989	        CopyOutScale1(rowIdx);
990	        CopyOutScale2(rowIdx);
991	    }
