// AscendC DynamicQuantV2 kernel
// Performs per-token asymmetric int8 quantization:
//   1. Cast input to FP32
//   2. If smooth: x = x * smooth
//   3. Per-row amax/amin reduction
//   4. scale = max((amax - amin) / 255, eps)
//   5. offset = 127 - amax / scale
//   6. q = rint(x/scale + offset).clamp(-128,127) -> int8
// Strategy: single_row per row processing (N is small to moderate)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Data movement helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(AscendC::LocalTensor<T> &dst,
                                   AscendC::GlobalTensor<T> src,
                                   uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(AscendC::GlobalTensor<T> dst,
                                    AscendC::LocalTensor<T> &src,
                                    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline void CastInputToFloat(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// DynamicQuantV2 Kernel — single row strategy
// =========================================================================

template <typename dataType>
class DynamicQuantV2Kernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR smooth, GM_ADDR y,
        GM_ADDR scale_out, GM_ADDR offset_out,
        int32_t M, int32_t N, int32_t blockM,
        int32_t usedCoreNum, int32_t tasksPerCore,
        float eps, float inv255, int64_t hasSmooth)
    {
        this->M_ = M;
        this->N_ = N;
        this->blockM_ = blockM;
        this->usedCoreNum_ = usedCoreNum;
        this->tasksPerCore_ = tasksPerCore;
        this->eps_ = eps;
        this->inv255_ = inv255;
        this->hasSmooth_ = hasSmooth;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
                             static_cast<uint64_t>(M) * N);
        smoothGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y),
                             static_cast<uint64_t>(M) * N);
        scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale_out), M);
        offsetGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(offset_out), M);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM_ / AscendC::GetSubBlockNum();

        // Input queue: one row of x
        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, N_ * sizeof(dataType));

        // Smooth 1D buffer (pre-loaded if has_smooth)
        if (hasSmooth_ != 0) {
            pipe_.InitBuffer(smoothBuf_, N_ * sizeof(dataType));
        }

        // Output queues
        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, N_ * sizeof(int8_t));
        pipe_.InitBuffer(scaleOutQueue_, BUFFER_NUM, sizeof(float));
        pipe_.InitBuffer(offsetOutQueue_, BUFFER_NUM, sizeof(float));

        // Compute buffers (FP32)
        pipe_.InitBuffer(xFp32Buf_, N_ * sizeof(float));
        pipe_.InitBuffer(tempBufA_, N_ * sizeof(float));
        pipe_.InitBuffer(tempBufB_, N_ * sizeof(float));
        pipe_.InitBuffer(scaleBuf_, sizeof(float));
        pipe_.InitBuffer(offsetBuf_, sizeof(float));
        pipe_.InitBuffer(reduceTmpBuf_, 2 * N_ * sizeof(float));
        pipe_.InitBuffer(quantHalfBuf_, N_ * sizeof(half));

        // Cast buffers for fp16/bf16
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe_.InitBuffer(xCastBuf_, N_ * sizeof(float));
            pipe_.InitBuffer(smoothCastBuf_, N_ * sizeof(float));
        }

        // Pre-load smooth (if has_smooth)
        if (hasSmooth_ != 0) {
            smoothInLocal_ = smoothBuf_.Get<dataType>();
            LoadGmToUb(smoothInLocal_, smoothGM_, static_cast<uint32_t>(N_));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            CastInputToFloat<dataType>(smoothFp32Local_, smoothInLocal_, smoothCastBuf_, N_);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();
            const int mNum = (M_ + blockM_ - 1) / blockM_;

            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                const int bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= mNum) { continue; }
                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM_ + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M_) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        CopyIn(rowIdx);
        Compute();
        CopyOut(rowIdx);
    }

    __aicore__ inline void CopyIn(int32_t rowIdx)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N_],
                   static_cast<uint32_t>(N_));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOut(int32_t rowIdx)
    {
        // y (int8)
        yOutLocal_ = yOutQueue_.DeQue<int8_t>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N_], yOutLocal_,
                    static_cast<uint32_t>(N_));
        yOutQueue_.FreeTensor(yOutLocal_);

        // scale (float32)
        scaleOutLocal_ = scaleOutQueue_.DeQue<float>();
        StoreUbToGm(scaleGM_[rowIdx], scaleOutLocal_, 1);
        scaleOutQueue_.FreeTensor(scaleOutLocal_);

        // offset (float32)
        offsetOutLocal_ = offsetOutQueue_.DeQue<float>();
        StoreUbToGm(offsetGM_[rowIdx], offsetOutLocal_, 1);
        offsetOutQueue_.FreeTensor(offsetOutLocal_);
    }

    __aicore__ inline void Compute()
    {
        // Allocate output tensors
        yOutLocal_ = yOutQueue_.AllocTensor<int8_t>();
        scaleOutLocal_ = scaleOutQueue_.AllocTensor<float>();
        offsetOutLocal_ = offsetOutQueue_.AllocTensor<float>();

        // Get compute buffers
        AscendC::LocalTensor<float> xFp32 = xFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
        AscendC::LocalTensor<float> scaleLocal = scaleBuf_.Get<float>();
        AscendC::LocalTensor<float> offsetLocal = offsetBuf_.Get<float>();
        AscendC::LocalTensor<float> reduceTmp = reduceTmpBuf_.Get<float>();
        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();

        // DeQue input
        xInLocal_ = xInQueue_.DeQue<dataType>();

        // Cast x to FP32
        CastInputToFloat<dataType>(xFp32, xInLocal_, xCastBuf_, N_);

        // If has_smooth, multiply
        if (hasSmooth_ != 0) {
            AscendC::Mul(xFp32, xFp32, smoothFp32Local_, N_);
        }

        // ---- Step 1: amax = reduce_max(xFp32, dim=-1) ----
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::ReduceMax<float>(tempA, xFp32, reduceTmp, N_);
        AscendC::PipeBarrier<PIPE_ALL>();
        float amaxVal = tempA.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // ---- Step 2: amin = reduce_min(xFp32, dim=-1) ----
        AscendC::ReduceMin<float>(tempB, xFp32, reduceTmp, N_);
        AscendC::PipeBarrier<PIPE_ALL>();
        float aminVal = tempB.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // ---- Step 3: scale = max((amax - amin) / 255, eps) ----
        float diffVal = amaxVal - aminVal;
        float rawScale = diffVal * inv255_;
        float scaleVal = (rawScale > eps_) ? rawScale : eps_;

        // ---- Step 4: offset = 127 - amax / scale ----
        float offsetVal = 127.0f - amaxVal / scaleVal;

        // Write scale and offset (non-broadcasted scalars)
        AscendC::Duplicate(scaleLocal, scaleVal, 1);
        AscendC::Duplicate(offsetLocal, offsetVal, 1);
        AscendC::DataCopy(scaleOutLocal_, scaleLocal, 1);
        AscendC::DataCopy(offsetOutLocal_, offsetLocal, 1);

        // ---- Step 5: q = rint(x / scale + offset), clamp [-128,127] ----
        AscendC::Muls(tempA, xFp32, 1.0f / scaleVal, N_);
        AscendC::Adds(tempA, tempA, offsetVal, N_);
        AscendC::Maxs(tempA, tempA, -128.0f, N_);
        AscendC::Mins(tempA, tempA, 127.0f, N_);

        // Cast: float32 -> half (intermediate) -> int8
        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N_);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(yOutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N_);

        // EnQue outputs
        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
        scaleOutQueue_.EnQue(scaleOutLocal_);
        offsetOutQueue_.EnQue(offsetOutLocal_);
    }

private:
    int32_t M_ = 0, N_ = 0, blockM_ = 0;
    int32_t usedCoreNum_ = 0, tasksPerCore_ = 0;
    float eps_ = 0.0f, inv255_ = 0.0f;
    int64_t hasSmooth_ = 0;
    int32_t subBlockRows_ = 0;

    AscendC::TPipe pipe_;

    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> smoothGM_;
    AscendC::GlobalTensor<int8_t> yGM_;
    AscendC::GlobalTensor<float> scaleGM_, offsetGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> scaleOutQueue_, offsetOutQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> smoothBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xFp32Buf_, tempBufA_, tempBufB_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_, offsetBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmpBuf_, quantHalfBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_, smoothCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> smoothInLocal_;
    AscendC::LocalTensor<int8_t> yOutLocal_;
    AscendC::LocalTensor<float> scaleOutLocal_, offsetOutLocal_;
    AscendC::LocalTensor<float> smoothFp32Local_;
};

// =========================================================================
// Dtype dispatch helper
// =========================================================================

__aicore__ inline void DispatchDynamicQuantV2(
    GM_ADDR x, GM_ADDR smooth, GM_ADDR y,
    GM_ADDR scale_out, GM_ADDR offset_out,
    int32_t M, int32_t N, int32_t blockM,
    int32_t usedCoreNum, int32_t tasksPerCore,
    float eps, float inv255, int64_t hasSmooth, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        DynamicQuantV2Kernel<float> kernel;
        kernel.Init(x, smooth, y, scale_out, offset_out,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    eps, inv255, hasSmooth);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        DynamicQuantV2Kernel<half> kernel;
        kernel.Init(x, smooth, y, scale_out, offset_out,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    eps, inv255, hasSmooth);
        kernel.Process();
    } else {
        DynamicQuantV2Kernel<bfloat16_t> kernel;
        kernel.Init(x, smooth, y, scale_out, offset_out,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    eps, inv255, hasSmooth);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void dynamic_quant_v2(
    GM_ADDR x, GM_ADDR smooth, GM_ADDR y,
    GM_ADDR scale_out, GM_ADDR offset_out,
    int32_t M, int32_t N, int32_t blockM,
    int32_t usedCoreNum, int32_t tasksPerCore,
    float eps, float inv255, int64_t hasSmooth, int64_t dtypeFlag)
{
    DispatchDynamicQuantV2(
        x, smooth, y, scale_out, offset_out,
        M, N, blockM, usedCoreNum, tasksPerCore,
        eps, inv255, hasSmooth, dtypeFlag);
}
