31	namespace ascend_kernel {
32	
33	std::vector<at::Tensor> add_rms_norm_dynamic_quant_v2(
34	    const at::Tensor &x1, const at::Tensor &x2,
35	    const at::Tensor &gamma, const at::Tensor &beta, double eps,
36	    const at::Tensor &smooth1, const at::Tensor &smooth2)
37	{
38	    TORCH_CHECK(x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
39	                   x1.scalar_type() == at::kBFloat16,
40	        "x1 must be float16, float32, or bfloat16");
41	    TORCH_CHECK(x1.scalar_type() == x2.scalar_type(),
42	        "x1 and x2 must have the same dtype");
43	    TORCH_CHECK(gamma.scalar_type() == x1.scalar_type(),
44	        "gamma must have the same dtype as x1/x2");
45	    TORCH_CHECK(beta.scalar_type() == x1.scalar_type(),
46	        "beta must have the same dtype as x1/x2");
47	    TORCH_CHECK(smooth1.scalar_type() == x1.scalar_type(),
48	        "smooth1 must have the same dtype as x1/x2");
49	    TORCH_CHECK(smooth2.scalar_type() == x1.scalar_type(),
50	        "smooth2 must have the same dtype as x1/x2");
51	    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [N]");
52	    TORCH_CHECK(beta.dim() == 1, "beta must be 1D [N]");
53	    TORCH_CHECK(x1.sizes().back() == gamma.sizes()[0],
54	        "gamma shape mismatch");
55	    TORCH_CHECK(x1.sizes() == x2.sizes(), "x1 and x2 must have the same shape");
56	
57	    auto origShape = x1.sizes();
58	    int32_t N = static_cast<int32_t>(x1.sizes().back());
