std::vector<at::Tensor> dynamic_quant_v2(
    const at::Tensor &x,
    const c10::optional<at::Tensor> &smooth_opt,
    const c10::optional<at::Tensor> &group_index)
{
    // ---- Input validation ----
    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
        "x must be float32, float16, or bfloat16");
    TORCH_CHECK(x.dim() >= 2, "x must have at least 2 dimensions");

    bool hasSmooth = smooth_opt.has_value();

    // ---- Flatten to 2D ----
    auto origShape = x.sizes();
    int32_t N = static_cast<int32_t>(x.sizes().back());
    int64_t M_raw = x.numel() / N;
    int32_t M = static_cast<int32_t>(M_raw);

    at::Tensor x_2d = x.contiguous().view({M_raw, N});

    // Prepare smooth tensor
    at::Tensor smooth_1d;
    if (hasSmooth) {
        at::Tensor smooth_val = *smooth_opt;
        smooth_1d = smooth_val.to(x.device()).to(x.scalar_type()).contiguous();
        TORCH_CHECK(smooth_1d.numel() == N,
            "smooth must have same size as last dim of x");
    } else {
        smooth_1d = at::empty({N},
            at::TensorOptions().dtype(x.scalar_type()).device(x.device()));
    }

    // ---- Tiling computation ----
    int32_t blockM = DEFAULT_BLOCK_M;
    int32_t mNum = (M + blockM - 1) / blockM;

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
    int32_t usedCoreNum = std::min<int32_t>(
        DEFAULT_NUM_PHYSICAL_CORES,
        std::max<int32_t>(1, std::min(mNum, coreNum)));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // ---- Create output tensors ----
    at::Tensor y = at::empty({M_raw, N},
        at::TensorOptions().dtype(at::kChar).device(x.device()));
    at::Tensor scale = at::empty({M_raw},
        at::TensorOptions().dtype(at::kFloat).device(x.device()));
    at::Tensor offset = at::empty({M_raw},
        at::TensorOptions().dtype(at::kFloat).device(x.device()));

    // ---- dtype flag: 0=fp32, 1=fp16, 2=bf16 ----
    int64_t dtypeFlag = 0;
    if (x_2d.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x_2d.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    int64_t hasSmoothVal = hasSmooth ? 1 : 0;
    float eps = 1e-12f;
    float inv255 = 1.0f / 255.0f;

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t _M = M;
    int32_t _N = N;
    int32_t _blockM = blockM;
    int32_t _usedCoreNum = usedCoreNum;
    int32_t _tasksPerCore = tasksPerCore;
    float _eps = eps;
    float _inv255 = inv255;
    int64_t _hasSmooth = hasSmoothVal;
    int64_t _dtypeFlag = dtypeFlag;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(dynamic_quant_v2, blockDim,
                    x_2d, smooth_1d, y, scale, offset,
                    _M, _N, _blockM, _usedCoreNum, _tasksPerCore,
                    _eps, _inv255, _hasSmooth, _dtypeFlag);

    // ---- Reshape outputs back to original shape ----
    y = y.view(origShape);

    std::vector<int64_t> reduceShape(origShape.begin(), origShape.end() - 1);
    if (reduceShape.empty()) {
        reduceShape = {1};
    }
    scale = scale.view(reduceShape);
    offset = offset.view(reduceShape);

    return {y, scale, offset};
}

}  // namespace ascend_kernel
