                    eps, inv255, hasSmooth);
        kernel.Process();
    } else {
        DynamicQuantV2Kernel<bfloat16_t> kernel;
        kernel.Init(x, smooth, y, scale_out, offset_out,
                    M, N, blockM, usedCoreNum, tasksPerCore,
                    eps, inv255, hasSmooth);
        kernel.Process();
    }
}

