// AscendC DynamicQuantV2 kernel
// Per-token asymmetric int8 quantization with optional smooth scaling

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

template <typename dataType>
class DynamicQuantV2Kernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR smooth, GM_ADDR y,
        GM_ADDR scale_out, GM_ADDR offset_out,
        int32_t M, int32_t N, int32_t blockM,
        int32_t usedCoreNum, int32_t tasksPerCore,
        float eps, float inv255, int64_t hasSmooth)
    {
        this->M_ = M; this->N_ = N; this->blockM_ = blockM;
        this->usedCoreNum_ = usedCoreNum; this->tasksPerCore_ = tasksPerCore;
        this->eps_ = eps; this->inv255_ = inv255; this->hasSmooth_ = hasSmooth;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
            static_cast<uint64_t>(M) * N);
        smoothGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth), N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y),
            static_cast<uint64_t>(M) * N);
        scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale_out), M);
        offsetGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(offset_out), M);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM_ / AscendC::GetSubBlockNum();

        // All buffers 32-byte aligned for DataCopyPad safety
        uint32_t n32_dt = (static_cast<uint32_t>(N_) * sizeof(dataType) + 31U) & ~31U;
        uint32_t n32_i8 = (static_cast<uint32_t>(N_) * sizeof(int8_t) + 31U) & ~31U;
        uint32_t n32_f32 = (static_cast<uint32_t>(N_) * sizeof(float) + 31U) & ~31U;
        uint32_t n32_half = (static_cast<uint32_t>(N_) * sizeof(half) + 31U) & ~31U;
        uint32_t n32_rtmp = (2U * static_cast<uint32_t>(N_) * sizeof(float) + 31U) & ~31U;
        uint32_t s32_f32 = 32U; // sizeof(float)=4, padded to 32

        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, n32_dt);
        pipe_.InitBuffer(smoothBuf_, n32_dt);
        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, n32_i8);
        pipe_.InitBuffer(scaleOutQueue_, BUFFER_NUM, s32_f32);
        pipe_.InitBuffer(offsetOutQueue_, BUFFER_NUM, s32_f32);
        pipe_.InitBuffer(xFp32Buf_, n32_f32);
        pipe_.InitBuffer(tempBufA_, n32_f32);
        pipe_.InitBuffer(tempBufB_, n32_f32);
        pipe_.InitBuffer(reduceTmpBuf_, n32_rtmp);
        pipe_.InitBuffer(quantHalfBuf_, n32_half);
        pipe_.InitBuffer(xCastBuf_, n32_f32);
        pipe_.InitBuffer(smoothCastBuf_, n32_f32);
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int subBlockIdx = AscendC::GetSubBlockIdx();
            int mNum = (M_ + blockM_ - 1) / blockM_;
            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int bx = coreIdx * tasksPerCore_ + localIdx;
                if (bx >= mNum) continue;
                for (int row = 0; row < subBlockRows_; ++row) {
                    int rowIdx = bx * blockM_ + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx >= M_) continue;
                    CopyIn(rowIdx);
                    Compute();
                    CopyOut(rowIdx);
                }
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t rowIdx)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        uint32_t nBytes = static_cast<uint32_t>(N_) * static_cast<uint32_t>(sizeof(dataType));
        AscendC::DataCopyExtParams cp{1, nBytes, 0, 0, 0};
        AscendC::DataCopyPadExtParams<dataType> pp{true, 0, 0, static_cast<dataType>(0)};
        AscendC::DataCopyPad(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N_], cp, pp);
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOut(int32_t rowIdx)
    {
        yOutLocal_ = yOutQueue_.DeQue<int8_t>();
        uint32_t yBytes = static_cast<uint32_t>(N_) * static_cast<uint32_t>(sizeof(int8_t));
        AscendC::DataCopyExtParams cp{1, yBytes, 0, 0, 0};
        AscendC::DataCopyPad(yGM_[static_cast<uint64_t>(rowIdx) * N_], yOutLocal_, cp);
        yOutQueue_.FreeTensor(yOutLocal_);

        scaleOutLocal_ = scaleOutQueue_.DeQue<float>();
        AscendC::DataCopyExtParams cpS{1, 4U, 0, 0, 0};
        AscendC::DataCopyPad(scaleGM_[rowIdx], scaleOutLocal_, cpS);
        scaleOutQueue_.FreeTensor(scaleOutLocal_);

        offsetOutLocal_ = offsetOutQueue_.DeQue<float>();
        AscendC::DataCopyPad(offsetGM_[rowIdx], offsetOutLocal_, cpS);
        offsetOutQueue_.FreeTensor(offsetOutLocal_);
    }

    __aicore__ inline void Compute()
    {
        yOutLocal_ = yOutQueue_.AllocTensor<int8_t>();
        scaleOutLocal_ = scaleOutQueue_.AllocTensor<float>();
        offsetOutLocal_ = offsetOutQueue_.AllocTensor<float>();

        AscendC::LocalTensor<float> xFp32 = xFp32Buf_.Get<float>();
        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
        AscendC::LocalTensor<float> reduceTmp = reduceTmpBuf_.Get<float>();
        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();

        // DeQue input
        xInLocal_ = xInQueue_.DeQue<dataType>();

        // Cast x to FP32
        if constexpr (std::is_same_v<dataType, float>) {
            xFp32 = xInLocal_.template ReinterpretCast<float>();
        } else {
            AscendC::LocalTensor<float> castBuf = xCastBuf_.Get<float>();
            AscendC::Cast(castBuf, xInLocal_, AscendC::RoundMode::CAST_NONE, N_);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopy(xFp32, castBuf, N_);
        }

        // Optionally multiply by smooth
        if (hasSmooth_ != 0) {
            AscendC::LocalTensor<dataType> smoothLocal = smoothBuf_.Get<dataType>();
            uint32_t nBytes = static_cast<uint32_t>(N_) * static_cast<uint32_t>(sizeof(dataType));
            AscendC::DataCopyExtParams cp{1, nBytes, 0, 0, 0};
            AscendC::DataCopyPadExtParams<dataType> pp{true, 0, 0, static_cast<dataType>(0)};
            AscendC::DataCopyPad(smoothLocal, smoothGM_, cp, pp);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();

            if constexpr (std::is_same_v<dataType, float>) {
                AscendC::LocalTensor<float> smoothFp32 =
                    smoothLocal.template ReinterpretCast<float>();
                AscendC::Mul(xFp32, xFp32, smoothFp32, N_);
            } else {
                AscendC::LocalTensor<float> castBuf = smoothCastBuf_.Get<float>();
                AscendC::Cast(castBuf, smoothLocal, AscendC::RoundMode::CAST_NONE, N_);
                AscendC::PipeBarrier<PIPE_ALL>();
                AscendC::Mul(xFp32, xFp32, castBuf, N_);
            }
        }

        // ReduceMax
        AscendC::ReduceMax<float>(tempA, xFp32, reduceTmp, N_);
        AscendC::PipeBarrier<PIPE_ALL>();
        float amaxVal = tempA.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // ReduceMin
        AscendC::ReduceMin<float>(tempB, xFp32, reduceTmp, N_);
        AscendC::PipeBarrier<PIPE_ALL>();
        float aminVal = tempB.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // Compute scale, offset
        float diffVal = amaxVal - aminVal;
        float rawScale = diffVal * inv255_;
        float scaleVal = (rawScale > eps_) ? rawScale : eps_;
        float offsetVal = 127.0f - amaxVal / scaleVal;

        // Write scalar outputs
        AscendC::Duplicate(scaleOutLocal_, scaleVal, 1);
        AscendC::Duplicate(offsetOutLocal_, offsetVal, 1);

        // Quantize: x/scale + offset, clamp, cast to int8
        float invScale = 1.0f / scaleVal;
        AscendC::Muls(tempA, xFp32, invScale, N_);
        AscendC::Adds(tempA, tempA, offsetVal, N_);
        AscendC::Maxs(tempA, tempA, -128.0f, N_);
        AscendC::Mins(tempA, tempA, 127.0f, N_);
        AscendC::PipeBarrier<PIPE_V>();

        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N_);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Cast(yOutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N_);

        xInQueue_.FreeTensor(xInLocal_);
        yOutQueue_.EnQue(yOutLocal_);
        scaleOutQueue_.EnQue(scaleOutLocal_);
        offsetOutQueue_.EnQue(offsetOutLocal_);
    }

    int32_t M_ = 0, N_ = 0, blockM_ = 0, usedCoreNum_ = 0;
    int32_t tasksPerCore_ = 0, subBlockRows_ = 0;
