5	
6	// DynamicQuantV2 AscendC kernel - minimal debug version
7	// Single_row strategy
8	
9	#include "kernel_operator.h"
10	
11	constexpr int32_t BUFFER_NUM = 1;
12	
13	template <typename dataType>
14	class DynamicQuantV2Kernel {
15	public:
16	    __aicore__ inline void Init(
17	        GM_ADDR x, GM_ADDR smooth, GM_ADDR y,
18	        GM_ADDR scale_out, GM_ADDR offset_out,
19	        int32_t M, int32_t N, int32_t blockM,
20	        int32_t usedCoreNum, int32_t tasksPerCore,
21	        float eps, float inv255, int64_t hasSmooth)
22	    {
23	        this->M_ = M; this->N_ = N; this->blockM_ = blockM;
24	        this->usedCoreNum_ = usedCoreNum; this->tasksPerCore_ = tasksPerCore;
25	        this->eps_ = eps; this->inv255_ = inv255; this->hasSmooth_ = hasSmooth;
26	
27	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
28	        smoothGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(smooth), N);
29	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y), static_cast<uint64_t>(M) * N);
30	        scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale_out), M);
31	        offsetGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(offset_out), M);
32	
33	        if ASCEND_IS_AIV { InitAivBuffers(); }
34	    }
35	
36	    __aicore__ inline void InitAivBuffers()
37	    {
38	        subBlockRows_ = blockM_ / AscendC::GetSubBlockNum();
39	        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, N_ * sizeof(dataType));
40	        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, N_ * sizeof(int8_t));
41	        pipe_.InitBuffer(scaleOutQueue_, BUFFER_NUM, sizeof(float));
42	        pipe_.InitBuffer(offsetOutQueue_, BUFFER_NUM, sizeof(float));
43	        pipe_.InitBuffer(xFp32Buf_, N_ * sizeof(float));
44	        pipe_.InitBuffer(tempBufA_, N_ * sizeof(float));
45	        pipe_.InitBuffer(tempBufB_, N_ * sizeof(float));
46	        pipe_.InitBuffer(reduceTmpBuf_, 2 * N_ * sizeof(float));
47	        pipe_.InitBuffer(quantHalfBuf_, N_ * sizeof(half));
48	        pipe_.InitBuffer(xCastBuf_, N_ * sizeof(float));
49	    }
50	
51	    __aicore__ inline void Process()
52	    {
53	        if ASCEND_IS_AIV {
54	            int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
55	            int subBlockIdx = AscendC::GetSubBlockIdx();
56	            int mNum = (M_ + blockM_ - 1) / blockM_;
57	            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
58	                int bx = coreIdx * tasksPerCore_ + localIdx;
59	                if (bx >= mNum) continue;
60	                for (int row = 0; row < subBlockRows_; ++row) {
61	                    int rowIdx = bx * blockM_ + subBlockIdx * subBlockRows_ + row;
62	                    if (rowIdx >= M_) continue;
63	                    CopyIn(rowIdx);
64	                    Compute();
65	                    CopyOut(rowIdx);
66	                }
67	            }
68	        }
69	    }
70	
71	private:
72	    __aicore__ inline void CopyIn(int32_t rowIdx)
73	    {
74	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
75	        uint32_t xBytes = static_cast<uint32_t>(N_) * static_cast<uint32_t>(sizeof(dataType));
76	        AscendC::DataCopyExtParams cp{1, xBytes, 0, 0, 0};
77	        AscendC::DataCopyPadExtParams<dataType> pp{true, 0, 0, static_cast<dataType>(0)};
78	        AscendC::DataCopyPad(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N_], cp, pp);
79	        xInQueue_.EnQue(xInLocal_);
80	    }
81	
82	    __aicore__ inline void CopyOut(int32_t rowIdx)
83	    {
84	        yOutLocal_ = yOutQueue_.DeQue<int8_t>();
85	        uint32_t yBytes = static_cast<uint32_t>(N_) * static_cast<uint32_t>(sizeof(int8_t));
86	        AscendC::DataCopyExtParams cp{1, yBytes, 0, 0, 0};
87	        AscendC::DataCopyPad(yGM_[static_cast<uint64_t>(rowIdx) * N_], yOutLocal_, cp);
88	        yOutQueue_.FreeTensor(yOutLocal_);
89	
90	        scaleOutLocal_ = scaleOutQueue_.DeQue<float>();
91	        AscendC::DataCopyExtParams cpS{1, sizeof(float), 0, 0, 0};
92	        AscendC::DataCopyPad(scaleGM_[rowIdx], scaleOutLocal_, cpS);
93	        scaleOutQueue_.FreeTensor(scaleOutLocal_);
94	
95	        offsetOutLocal_ = offsetOutQueue_.DeQue<float>();
96	        AscendC::DataCopyPad(offsetGM_[rowIdx], offsetOutLocal_, cpS);
97	        offsetOutQueue_.FreeTensor(offsetOutLocal_);
98	    }
99	
100	    __aicore__ inline void Compute()
101	    {
102	        yOutLocal_ = yOutQueue_.AllocTensor<int8_t>();
103	        scaleOutLocal_ = scaleOutQueue_.AllocTensor<float>();
104	        offsetOutLocal_ = offsetOutQueue_.AllocTensor<float>();
105	
106	        AscendC::LocalTensor<float> xFp32 = xFp32Buf_.Get<float>();
107	        AscendC::LocalTensor<float> tempA = tempBufA_.Get<float>();
108	        AscendC::LocalTensor<float> tempB = tempBufB_.Get<float>();
109	        AscendC::LocalTensor<float> reduceTmp = reduceTmpBuf_.Get<float>();
110	        AscendC::LocalTensor<half> quantHalf = quantHalfBuf_.Get<half>();
111	
112	        // DeQue input
113	        xInLocal_ = xInQueue_.DeQue<dataType>();
114	
115	        // Cast to FP32
116	        if constexpr (std::is_same_v<dataType, float>) {
117	            xFp32 = xInLocal_.template ReinterpretCast<float>();
118	        } else {
119	            AscendC::LocalTensor<float> castBuf = xCastBuf_.Get<float>();
120	            AscendC::Cast(castBuf, xInLocal_, AscendC::RoundMode::CAST_NONE, N_);
121	            AscendC::PipeBarrier<PIPE_V>();
122	            AscendC::DataCopy(xFp32, castBuf, N_);
123	        }
124	
125	        // ReduceMax
126	        AscendC::ReduceMax<float>(tempA, xFp32, reduceTmp, N_);
127	        AscendC::PipeBarrier<PIPE_ALL>();
128	        float amaxVal = tempA.GetValue(0);
129	        AscendC::PipeBarrier<PIPE_ALL>();
130	
131	        // ReduceMin
132	        AscendC::ReduceMin<float>(tempB, xFp32, reduceTmp, N_);
133	        AscendC::PipeBarrier<PIPE_ALL>();
134	        float aminVal = tempB.GetValue(0);
135	        AscendC::PipeBarrier<PIPE_ALL>();
136	
137	        // Compute scale, offset
138	        float diffVal = amaxVal - aminVal;
139	        float rawScale = diffVal * inv255_;
140	        float scaleVal = (rawScale > eps_) ? rawScale : eps_;
141	        float offsetVal = 127.0f - amaxVal / scaleVal;
142	
143	        // Write scalar outputs via Duplicate on VECOUT tensor
144	        AscendC::Duplicate(scaleOutLocal_, scaleVal, 1);
145	        AscendC::Duplicate(offsetOutLocal_, offsetVal, 1);
146	
147	        // Quantize: x/scale + offset, clamp, cast to int8
148	        float invScale = 1.0f / scaleVal;
149	        AscendC::Muls(tempA, xFp32, invScale, N_);
150	        AscendC::Adds(tempA, tempA, offsetVal, N_);
151	        AscendC::Maxs(tempA, tempA, -128.0f, N_);
152	        AscendC::Mins(tempA, tempA, 127.0f, N_);
153	        AscendC::PipeBarrier<PIPE_V>();
154	
155	        AscendC::Cast(quantHalf, tempA, AscendC::RoundMode::CAST_NONE, N_);
156	        AscendC::PipeBarrier<PIPE_V>();
157	        AscendC::Cast(yOutLocal_, quantHalf, AscendC::RoundMode::CAST_RINT, N_);
158	
159	        xInQueue_.FreeTensor(xInLocal_);
160	        yOutQueue_.EnQue(yOutLocal_);
161	        scaleOutQueue_.EnQue(scaleOutLocal_);
162	        offsetOutQueue_.EnQue(offsetOutLocal_);
163	    }
164	
165	    int32_t M_ = 0, N_ = 0, blockM_ = 0, usedCoreNum_ = 0;
166	    int32_t tasksPerCore_ = 0, subBlockRows_ = 0;
167	    float eps_ = 0.0f, inv255_ = 0.0f;
168	    int64_t hasSmooth_ = 0;
169	
170	    AscendC::TPipe pipe_;
171	    AscendC::GlobalTensor<dataType> xGM_, smoothGM_;
172	    AscendC::GlobalTensor<int8_t> yGM_;
173	    AscendC::GlobalTensor<float> scaleGM_, offsetGM_;
174	
175	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
176	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
177	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> scaleOutQueue_, offsetOutQueue_;
178	
179	    AscendC::TBuf<AscendC::TPosition::VECCALC> xFp32Buf_, tempBufA_, tempBufB_;
180	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmpBuf_, quantHalfBuf_;
181	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
182	
183	    AscendC::LocalTensor<dataType> xInLocal_;
184	    AscendC::LocalTensor<int8_t> yOutLocal_;
185	    AscendC::LocalTensor<float> scaleOutLocal_, offsetOutLocal_;
186	};
187	
188	__aicore__ inline void DispatchDynamicQuantV2(
189	    GM_ADDR x, GM_ADDR smooth, GM_ADDR y,
190	    GM_ADDR scale_out, GM_ADDR offset_out,
191	    int32_t M, int32_t N, int32_t blockM,
192	    int32_t usedCoreNum, int32_t tasksPerCore,
193	    float eps, float inv255, int64_t hasSmooth, int64_t dtypeFlag)
194	{
195	    if (dtypeFlag == 0) {
196	        DynamicQuantV2Kernel<float> kernel;
197	        kernel.Init(x, smooth, y, scale_out, offset_out,
198	                    M, N, blockM, usedCoreNum, tasksPerCore, eps, inv255, hasSmooth);
199	        kernel.Process();
200	    } else if (dtypeFlag == 1) {
201	        DynamicQuantV2Kernel<half> kernel;
202	        kernel.Init(x, smooth, y, scale_out, offset_out,
203	                    M, N, blockM, usedCoreNum, tasksPerCore, eps, inv255, hasSmooth);
204	        kernel.Process();
205	    } else {
206	        DynamicQuantV2Kernel<bfloat16_t> kernel;
207	        kernel.Init(x, smooth, y, scale_out, offset_out,
208	                    M, N, blockM, usedCoreNum, tasksPerCore, eps, inv255, hasSmooth);
209	        kernel.Process();
210	    }
211	}
212	
213	extern "C" __global__ __aicore__ void dynamic_quant_v2(
214	    GM_ADDR x, GM_ADDR smooth, GM_ADDR y,
215	    GM_ADDR scale_out, GM_ADDR offset_out,
216	    int32_t M, int32_t N, int32_t blockM,
217	    int32_t usedCoreNum, int32_t tasksPerCore,
218	    float eps, float inv255, int64_t hasSmooth, int64_t dtypeFlag)
219	{
220	    DispatchDynamicQuantV2(x, smooth, y, scale_out, offset_out,
221	        M, N, blockM, usedCoreNum, tasksPerCore, eps, inv255, hasSmooth, dtypeFlag);
222	}
